    id: "acute-symptom-appraisal-delay-mi-stroke", section: "1461", title: "Acute Symptom-Appraisal Delay (Heart Attack & Stroke)", subtitle: "Degrades: Interoceptive & Meta-Cognitive threat-reading, survival",
    evidenceTag: "Strong",
    weakness: { threat: 7, weakLines: ["Interoceptive", "Meta-Cognitive", "Bodily"], degree: "primary driver", onset: "immediate", reversibility: "lasting" },
