    id: "soil-transmitted-helminths", section: "2366", title: "Soil-Transmitted Helminths — 1.5 Billion Worms, Contested Benefit of Deworming", subtitle: "Degrades: Bodily, Meta-Cognitive, Financial",
    evidenceTag: "Mixed",
    harm: { severity: 2, onset: "months", reversibility: "recovers" },
