    id: "newborn-metabolic-bloodspot-screening", section: "3820", title: "Newborn Blood-Spot (Heel-Prick) Metabolic Screening", subtitle: "practice: 'Bolsters clusters: cognitive integrity, thyroid/metabolic function, prevented intellectual disability'",
    evidenceTag: "Strong",
    impact: { magnitude: 5, latency: "days", durability: "lasting", effort: "low" },
