    id: "exponential-growth-bias-weakness", section: "3975", title: "Exponential-Growth Bias (Compound-Interest Neglect)", subtitle: "weakness: 'Degrades: Automatic Savings-Rate Escalation, Payday-Loan Debt Trap, Fee-Aware Investing'",
    evidenceTag: "Strong",
    weakness: { threat: 6, weakLines: ["Financial", "Mathematical"], degree: "major contributor", onset: "immediate", reversibility: "recovers" },
