    id: "autogenic-training", section: "4139", title: "Autogenic Training (Self-Suggested Relaxation)", subtitle: "practice: 'Bolsters clusters: Applied Relaxation, Breathwork / Slow-Paced Breathing, anxiety down-regulation'",
    evidenceTag: "Moderate",
    impact: { magnitude: 2, latency: "weeks", durability: "sustained", effort: "moderate" },
