    id: "home-country-bias", section: "4355", title: "Home-Country Bias — Under-Diversifying Geographically", subtitle: "weakness: 'Degrades: Financial, Strategic, diversification'",
    evidenceTag: "Moderate",
    weakness: { threat: 4, weakLines: ["Financial", "Strategic"], degree: "moderate contributor", onset: "years", reversibility: "recovers" },
    degrades: ["diversification", "risk-adjusted return", "Strategic resilience", "idiosyncratic-risk control"],
